from tkinter import *import tkinter as tkroot = tk.Tk()root.title("Двигающаяся кнопка")root.geometry("400x400")btn = tk.Button(root, text="Двигай меня", width=12, height=2)btn.place(x=150, y=150)def move(event):    # Текущие координаты кнопки    x = btn.winfo_x()    y = btn.winfo_y()    # Размеры кнопки и окна    w = btn.winfo_width()    h = btn.winfo_height()    W = root.winfo_width()    H = root.winfo_height()    if event.keysym == "Left":        x = max(0, x - 10)    elif event.keysym == "Right":        x = min(W - w, x + 10)    elif event.keysym == "Up":        y = max(0, y - 10)    elif event.keysym == "Down":        y = min(H - h, y + 10)    btn.place(x=x, y=y)root.bind("<Key>", move)btn.focus_set()root.mainloop()